import { ThresholdMarker } from '../ThresholdBar.js';

export function groupOverlappingMarkers(
  markers: ThresholdMarker[],
): ThresholdMarker[][] {
  const groups: ThresholdMarker[][] = [];
  const sortedByMin = [...markers].sort(
    (markerA, markerB) =>
      Math.min(markerA.y0, markerA.y1) - Math.min(markerB.y0, markerB.y1),
  );

  for (let i = 0; i < sortedByMin.length; i++) {
    const current = sortedByMin[i];
    const currentMin = Math.min(current.y0, current.y1);

    const groupIndex = groups.findIndex((group) =>
      group.some((value) => {
        const valueMax = Math.max(value.y0, value.y1);

        return currentMin < valueMax;
      }),
    );

    if (groupIndex !== -1) {
      groups[groupIndex].push(current);
    } else {
      groups.push([current]);
    }
  }

  return groups;
}
